def getYearsOfCover(inc_str:list, index_year:int):
    """ This function takes in 
        - inc_str which is the list of incs history
        - index_year which is the year associated with the first indexed inc in inc_str
        
        This function calculates the years of coverage according to pdf page 5 (or page 1333) in 1972 major pdf."""
    # Get the years_of_coverage pdf page 5 and page 1333 in 1972 major
    sum_wage_before_1951 = 0
    totalYOC = 0
    for i, earnings in enumerate(inc_str):
        current_year = index_year + i
        if current_year < 1951:
            sum_wage_before_1951 = sum_wage_before_1951 + earnings
        else:
            if earnings >= Thresholds.get(current_year):
                totalYOC = totalYOC + 1

    pre1951YOC = min(int(sum_wage_before_1951 // 900), 14) #Max 14 YOC under 1951.
    totalYOC + pre1951YOC + totalYOC
    return min(totalYOC, 30)



def indexing_calculator(income: int, income_year:int, birth_year:int):
    """This function takes a particular year of someone's income stream and turns the income into indexed earnings to be used to calculate aime.
    income: the nominal income in a particular year.
    income_year: the calendar year in which that income was received
    birth_year: the year in which the earner was born. This actually matters because incomes earned after age 60 are not indexed for point of aime
    """

    if birth_year + 60 in avg_wage_index.keys() and income_year in avg_wage_index.keys() and birth_year + 60 <= 2024:

        #print(income_year, " and ", birth_year+60)
        if income_year>=birth_year+60:
            index_factor=1
        else:
            index_factor=avg_wage_index[birth_year+60]/avg_wage_index[income_year] #be careful of the new year's day rule! I am unsure when this became active, but it seems to be active in the modern legislation and not active for the 1960s, unsure when it became active
            
        indexed_earnings=income*index_factor
        #print("indexed_earnings ", indexed_earnings)
        return indexed_earnings
    else:
        if income_year>=birth_year+60:
            index_factor=1
        else:
            index_factor=avg_wage_index[2024]/avg_wage_index[income_year] #be careful of the new year's day rule! I am unsure when this became active, but it seems to be active in the modern legislation and not active for the 1960s, unsure when it became active
            
        indexed_earnings=income*index_factor
        #print("indexed_earnings ", indexed_earnings)
        return indexed_earnings

def a_modern(adjusted_income_stream: list, original_income_stream:list,  index_year: int, birth_year: int, retirement_year:int, reference_year:int, woman:bool, death_year = 0) -> float:
    """ 
    This function takes an adjusted income stream, and then calculates the aime from it. It utilized the "indexing_calculator" function, and the "awi" dictionary present within the modern_amendment script.
    adjusted_income_stream: List of income adjusted for tax max
    index_year: The year corresponding to index 0 in the list of incomes
    birth_year: The person's birth year
    current_year: The year to which we must index inflation
    """

    #the following calculation of elapsed years can be found on 215(b)(2)
    
    # Define the starting year for elapsed years calculation
    
    start_year = max(1951, birth_year + 22)
    
    # Define the end year based on when the person retires, check this?
    if death_year != 0:
        end_year = max(1961,min(death_year,birth_year+62))
    else:
        end_year = max(1961, birth_year + 62)
    # Calculate elapsed years
    elapsed_years = max(0, end_year - start_year)
    if index_year<1951:
        adjusted_income_stream=adjusted_income_stream[1951-index_year:]
        index_year=1951
    # Compute benefit computation years (elapsed years - 5, but at least 2), is missing the scenario where people work less than 30 years
    benefit_computation_years = elapsed_years-5
    if benefit_computation_years < 2: benefit_computation_years = 2

    # Inflate all yearly wages
    indexed_income_stream=[]
    for i in range(len(adjusted_income_stream)):
        #print("Now its time for ", i, " and ", adjusted_income_stream[i], " to become ")
        indexed_income_stream.append(indexing_calculator(adjusted_income_stream[i],i+index_year, birth_year))


    #print("here here:")
    #print(indexed_income_stream)

    #print("indexed_income_stream: ", indexed_income_stream)

    # Select the highest benefit computation years
    top_inc_years = sorted(indexed_income_stream, reverse=True)[:benefit_computation_years]
    #print("top inc years: ", len(top_inc_years))
    # Calculate AIME: (Sum of top earnings) / (Months in benefit computation years)

    #print(sum(top_inc_years))

    aime = sum(top_inc_years) / (benefit_computation_years * 12)

    aime = math.trunc(aime)
    
    #print("the AIME is: ", aime)
    return aime
    
