def b_modern(income_stream:list, original_income_stream:list, index_year:int, birth_year:int, retirement_year:int, reference_year:int, woman:bool):
    """This function outputs the nominal monthly benefit (int) an individual would have received under the 1950 legislation. 
        The function inputs are (income_stream:list, index_year:int, birth_year:int).
        income_stream -- a list of nominal incomes a person received in each year.
        index_year -- the year in which an individual begins their income_stream.
        birth_year -- the year the individual is born.
        Reference year -- what years dollars you want the output to be in
    """ 

    monthly_benefits=0
    adjusted_income_stream=i_modern(income_stream, index_year, retirement_year)
    avg_monthly_wage=a_modern(adjusted_income_stream, original_income_stream, index_year, birth_year, retirement_year, reference_year, woman)
    monthly_benefits=bb_modern(adjusted_income_stream, original_income_stream, avg_monthly_wage, index_year, birth_year, retirement_year, reference_year,woman) 
    #monthly benefits are given in dollars of the year in which a person retires
    # deductions for retiring early, sec 202(q). 
    

    extraneous_months = 0


        
    if birth_year<1943:
        nra=65
        if birth_year == 1938: extraneous_months = 2
        if birth_year == 1939: extraneous_months = 4
        if birth_year == 1940: extraneous_months = 6
        if birth_year == 1941: extraneous_months = 8
        if birth_year == 1942: extraneous_months = 10

    elif birth_year>= 1943 and birth_year<1960:
        nra=66
        if birth_year == 1955: extraneous_months = 2
        if birth_year == 1956: extraneous_months = 4
        if birth_year == 1957: extraneous_months = 6
        if birth_year == 1958: extraneous_months = 8
        if birth_year == 1959: extraneous_months = 10

    elif birth_year>=1960:
        nra=67
    if (retirement_year-birth_year) <= nra:

        months = 12*(nra-(retirement_year-birth_year)) + extraneous_months
        early_deduction = (5/9) * 0.01 * min(36, months)
        if months > 36:
            early_deduction = early_deduction + (5/12) * 0.01* (months - 36)

        monthly_benefits=(1-early_deduction)*monthly_benefits
    

    temp_retirement_year = retirement_year
    if retirement_year > birth_year + 70: temp_retirement_year = birth_year + 70

    if (temp_retirement_year-birth_year)>nra:     #credits for retiring late, sec 202(w)
        if birth_year < 1916:
            applicable_percentage= (1/12) * 0.01
        elif birth_year > 1916 and birth_year < 1925:
            applicable_percentage= (1/4) * 0.01
        elif birth_year >= 1925 and birth_year < 1927: 
            applicable_percentage = (7/24) * 0.01        
        elif birth_year >= 1927 and birth_year < 1929: 
            applicable_percentage = (1/3) * 0.01
        elif birth_year >= 1929 and birth_year < 1931: 
            applicable_percentage = (3/8) * 0.01
        elif birth_year >= 1931 and birth_year < 1933: 
            applicable_percentage = (5/12) * 0.01
        elif birth_year >= 1933 and birth_year < 1935: 
            applicable_percentage = (11/24) * 0.01
        elif birth_year >= 1935 and birth_year < 1937: 
            applicable_percentage = (1/2) * 0.01
        elif birth_year >= 1937 and birth_year < 1939: 
            applicable_percentage = (13/24) * 0.01
        elif birth_year >= 1939 and birth_year < 1941: 
            applicable_percentage = (7/12) * 0.01
        elif birth_year >= 1941 and birth_year < 1943: 
            applicable_percentage = (5/8) * 0.01
        elif birth_year >= 1943:
            applicable_percentage= (2/3) * 0.01    
        prevnra = nra
        totalYears = 0 
        ageAtIndex = index_year - birth_year
        relevantInct = income_stream[0:max(0,nra - ageAtIndex+1)]
        #print("here: ", nra - ageAtIndex+1)
        while not qmodern(relevantInct, index_year, birth_year, retirement_year,woman):
            nra +=1
            extraneous_months = 0
            relevantInct = income_stream[0:max(0,nra - ageAtIndex+1)]
            #print(nra, " not qualified", relevantInct)



       #The following calculator determines the quarter in which an indviidual became eligible to begin collecting late retirement credits, then compiles them to the number of credits.
        quarterInWhichQEligible, yearInWhichQEligible = getQYYYQuarterQualified(relevantInct, index_year, birth_year, retirement_year) #if 0, then Q4, so 3 months. If 1, then Q3, so 6 months. if 2, then Q2, so 9 months
        #print(quarterInWhichQEligible, yearInWhichQEligible,prevnra + birth_year, nra + birth_year)
        if yearInWhichQEligible < prevnra + birth_year or yearInWhichQEligible > birth_year + 70: extraMonthsEligible = 0
        elif yearInWhichQEligible == prevnra + birth_year and quarterInWhichQEligible == 1: 
            extraMonthsEligible = 0
        else:
            if yearInWhichQEligible >= prevnra+birth_year and quarterInWhichQEligible != 1:
                totalYears = totalYears -1
                extraMonthsEligible = (4-quarterInWhichQEligible)*3 + 3 #If 4, then 3. If 3, then 6. If 2, then 9. If 1, then 12
                if yearInWhichQEligible == prevnra + birth_year:
                    if 3*quarterInWhichQEligible > extraneous_months: extraneous_months = 0
                    else: 
                        totalYears = totalYears +1
                        extraMonthsEligible = 0
            else: extraMonthsEligible = 0


        for year in range(birth_year + nra, retirement_year):
            if year - birth_year <= 70-1:
                totalYears +=1
        late_credit = 1+ (applicable_percentage) * (max(0,(totalYears) * 12- extraneous_months + extraMonthsEligible))
        #print("total years: ", totalYears, extraneous_months, extraMonthsEligible)
        #print("months: ", (max(0,(totalYears) * 12- extraneous_months + extraMonthsEligible)))
        

        monthly_benefits = monthly_benefits * late_credit

    indexed_monthly_benefits=monthly_benefits #explain how the inflation function works

    for i in range(retirement_year,reference_year): #This used to be birth + 62, but because of the special minimum, the PIA is now given indexed to the retirement year.
        if retirement_year == reference_year: continue
        cola = (1+cola_adjustments[i+1]) 
        if i == 1999 and retirement_year > 2001: 
            cola = 1.025 #Pursuant to Public Law 106-554
        indexed_monthly_benefits*=cola
    if reference_year >= 1983:
        return math.floor(indexed_monthly_benefits)
    else:
        return math.ceil(indexed_monthly_benefits * 10) / 10
    

