    #print("Avg: ", primary_avg_monthly_wage)
    primary_PIA = bb_modern(primary_adjusted_income_stream, primary_avg_monthly_wage, index_year,  birth_year,retirement_year,reference_year, woman)

    #print("primary pia: ", primary_PIA)

    colaAdjustedPIA=primary_PIA #explain how the inflation function works
    for i in range(retirement_year,reference_year):
        cola = (1+cola_adjustments[i+1]) 
        if i == 1999 and retirement_year > 2001: 
            cola = 1.025 #Pursuant to Public Law 106-554
        colaAdjustedPIA*=cola
   
    deduction = 1

    if spouse_retirement_year <= 1983:
        if spouse_birth_year + 65 > spouse_retirement_year:
            deduction = deduction - (25/36) * 0.01 * 12 *(spouse_birth_year+65 - spouse_retirement_year)
    else: 

        extraneous_months = 0
        
        if birth_year<1943:
            nra=65
            if birth_year == 1938: extraneous_months = 2
            if birth_year == 1939: extraneous_months = 4
            if birth_year == 1940: extraneous_months = 6
            if birth_year == 1941: extraneous_months = 8
            if birth_year == 1942: extraneous_months = 10

        elif birth_year>= 1943 and birth_year<1960:
            nra=66
            if birth_year == 1955: extraneous_months = 2
