def death_modern(income_stream:list, index_year:int, birth_year:int, retirement_year:int, reference_year:int,death_year:int, woman:bool, survivor:bool):
    """This function outputs the nominal death benefit an individual would have received under the 1950 legislation. 
        The death benefit was restricted in 1981 strictly to a surviving spouse or children receiving monthly benefits on the deceased's record (under 18 years of age)
        The function inputs are (income_stream:list, index_year:int, birth_year:int).
        income_stream -- a list of nominal incomes a person received in each year.
        index_year -- the year in which an individual begins their income_stream.
        birth_year -- the year the individual is born.
        death_year -- the year which the primary died
    """ 
    if qmodern(income_stream, index_year, birth_year, retirement_year, woman) and not survivor:
        monthlyBenefit = b_modern(income_stream, index_year, birth_year, retirement_year, death_year)
        return max(3 * monthlyBenefit, 255)
    else:
        return 0

