def MFB_modern(income_stream:list, index_year:int, birth_year:int, retirement_year:int, reference_year:int,death_year:int, woman:bool):
    """
    This function outputs the Maximum Family Benefit a principal beneficiary would be capped at under the relevant legislation.
     income_stream -- a list of nominal incomes a person received in each year.
        index_year -- the year in which an individual begins their income_stream.
        birth_year -- the year the individual is born.
        death_year -- the year which the primary died
        Reference year -- to which year would the dollars be indexed to. Likely the year in which the entitlement is being paid out.
    """
    primary_adjusted_income_stream=i_modern(income_stream, index_year, retirement_year)
    avg_monthly_wage = a_modern(primary_adjusted_income_stream, index_year, birth_year, retirement_year,reference_year, woman)
    #pia = bb_modern(primary_adjusted_income_stream, avg_monthly_wage, index_year,birth_year, retirement_year, reference_year, woman)

    


    if (retirement_year-birth_year)>62:
        quarterInWhichQEligible, yearInWhichQEligible = getQYYYQuarterQualified(primary_adjusted_income_stream, index_year, birth_year, retirement_year) #if 0, then Q4, so 3 months. If 1, then Q3, so 6 months. if 2, then Q2, so 9 months
    else: yearInWhichQEligible = birth_year + 62

    #print(yearInWhichQEligible)
    #Calculate PIA with original AMW, but eligibility bendpoints
    bend_point_1= 180
    bend_point_2=1085
    
    #print( yearInWhichQEligible - 2)
    bend_point_1=round(dollarConversion(bend_point_1, 1977, birth_year + 60))
    bend_point_2=round(dollarConversion(bend_point_2, 1977,  birth_year + 60))
    #print("bend point 1: ", bend_point_1, " BP2: ", bend_point_2)
    
    if avg_monthly_wage >= bend_point_2:
            pia = (bend_point_1 * 0.9) + ((bend_point_2-bend_point_1) * 0.32) + 0.15 * (avg_monthly_wage-bend_point_2)
    if avg_monthly_wage < bend_point_2 and avg_monthly_wage >= bend_point_1:
            pia = (bend_point_1 * 0.9) +  0.32 * (avg_monthly_wage-bend_point_1)
    if avg_monthly_wage <= bend_point_1:
            pia = avg_monthly_wage * 0.9 
    pia = round(pia, 3) #fixes floating point error
    #print("prepia: ", pia)
    if retirement_year < 1982:
        pia = math.ceil(10*pia) / 10
    else:
        pia = math.floor(10*pia) / 10
    

    bend_point_1=230
    bend_point_1_converted = round(dollarConversion(bend_point_1, 1977, birth_year + 60))
    bend_point_2=332
    bend_point_2_converted = round(dollarConversion(bend_point_2, 1977, birth_year + 60))
    bend_point_3 = 433
    bend_point_3_converted = round(dollarConversion(bend_point_3, 1977, birth_year + 60))
    base_year=1979


    if pia <= bend_point_1_converted:
        maximumFamilyBenefit = 1.5*pia
    elif pia <= bend_point_2_converted:
        maximumFamilyBenefit = 1.5 * bend_point_1_converted + (pia - bend_point_1_converted) * 2.72
    elif pia <= bend_point_3_converted:
        maximumFamilyBenefit = 1.5 * (bend_point_1_converted) + 2.72 * (bend_point_2_converted-bend_point_1_converted) + (pia - bend_point_2_converted) * 1.34
    else:
        maximumFamilyBenefit = 1.5 * bend_point_1_converted + 2.72 * (bend_point_2_converted-bend_point_1_converted) + 1.34 * (bend_point_3_converted-bend_point_2_converted) + (pia - bend_point_3_converted) * 1.75


    #print("PIA: ", pia)


    #Transitional Guarantee:
    if birth_year >= 1917 and birth_year <= 1921 and index_year < 1979: #Section 4 (A) page 9 of 1977 legislation 
        adjusted_income_stream = i1973(income_stream, index_year,retirement_year)
        transitionalConsideredYears = adjusted_income_stream[0: max(0,birth_year + 62 - index_year)]
        #print("trans: ", transitionalConsideredYears)
        AverageMonthlyWage = math.trunc(a1973(transitionalConsideredYears, index_year, birth_year,retirement_year, reference_year, True))

        #print(AverageMonthlyWage)

        pia_under_avg_wage = 0
        #print(AverageMonthlyWage)
        if birth_year + 62 >= 1982:
            for rowNum in range(len(col31982)):
                if (AverageMonthlyWage >= col31982[rowNum][0]) and (AverageMonthlyWage <= col31982[rowNum][1]):
                    pia_under_avg_wage = col41982[rowNum]
        else:
            for rowNum in range(len(col3)):

                if (AverageMonthlyWage >= col3[rowNum][0]) and (AverageMonthlyWage <= col3[rowNum][1]):
                    #print("hello!", col3[rowNum][0], AverageMonthlyWage, col3[rowNum][1])
                    pia_under_avg_wage = col4[rowNum]

        if not transitionalConsideredYears: pia_under_avg_wage = 0

        bend_point_1=230
        bend_point_1_converted = round(dollarConversion(bend_point_1, 1977, birth_year + 60))
        bend_point_2=332
        bend_point_2_converted = round(dollarConversion(bend_point_2, 1977, birth_year + 60))
        bend_point_3 = 433
        bend_point_3_converted = round(dollarConversion(bend_point_3, 1977, birth_year + 60))
        base_year=1979

        pia = pia_under_avg_wage
        if pia <= bend_point_1_converted:
            maximumFamilyBenefitTransitional = 1.5*pia
        elif pia <= bend_point_2_converted:
            maximumFamilyBenefitTransitional = 1.5 * bend_point_1_converted + (pia - bend_point_1_converted) * 2.72
        elif pia <= bend_point_3_converted:
            maximumFamilyBenefitTransitional = 1.5 * (bend_point_1_converted) + 2.72 * (bend_point_2_converted-bend_point_1_converted) + (pia - bend_point_2_converted) * 1.34
        else:
            maximumFamilyBenefitTransitional = 1.5 * bend_point_1_converted + 2.72 * (bend_point_2_converted-bend_point_1_converted) + 1.34 * (bend_point_3_converted-bend_point_2_converted) + (pia - bend_point_3_converted) * 1.75

        maximumFamilyBenefit = max(maximumFamilyBenefit, maximumFamilyBenefitTransitional)

    if birth_year + 62 < 1978 :
        yearsOfSpecialMinimumCoverage = getYearsOfCover(income_stream, index_year)
        if yearsOfSpecialMinimumCoverage > 10:
            specMinPIA = (yearsOfSpecialMinimumCoverage-10) * 11.5
            #We need to take the specialMinimumPIA from 1979 to the current year, regardless of when the individual turned 60.
            for i in range(1979,retirement_year):
                if i+1 in cola_adjustments.keys():
                    cola = (1+cola_adjustments[i+1]) 
                    if i == 1999 and retirement_year > 2001: 
                        cola = 1.025 #Pursuant to Public Law 106-554
                    specMinPIA*=cola
            pia = max(specMinPIA, pia)

    #print("the pre-frozen pia: ", pia)

    for i in range(birth_year + 62,reference_year): #This used to be birth + 62, but because of the special minimum, the PIA is now given indexed to the retirement year.
        cola = (1+cola_adjustments[i+1]) 
        if i == 1999 and retirement_year > 2001: 
            cola = 1.025 #Pursuant to Public Law 106-554
        maximumFamilyBenefit*=cola

    
    #Now, we implement the frozen minimum guaranteee:
    wasFrozenPIASuccessful = False
    if birth_year >= 1917 and birth_year <= 1919: #techincally, its only for people who become eligible to recieve benfits between 1979 and 1981 (inclusive)
        #if pia < 122: pia = 
        adjusted_income_stream = i1973(income_stream, index_year,retirement_year)
        transitionalConsideredYears = adjusted_income_stream[0: max(0,birth_year + 62 - index_year)]
        
        AverageMonthlyWage = math.trunc(a1973(transitionalConsideredYears, index_year, birth_year,retirement_year, reference_year, True))
        for rowNum in range(len(table1978)):
                if (AverageMonthlyWage >= table1978[rowNum][0]) and (AverageMonthlyWage <= table1978[rowNum][1]):
                    #print("hello!", table1978[rowNum][0], AverageMonthlyWage, table1978[rowNum][1])
                    pia_under_frozen_minumum = math.ceil(benefits1978[rowNum])
        for i in range(birth_year + 65,retirement_year):
            #print(i, "pia: ", TransitionPIA)
            cola = (1+cola_adjustments[i+1]) 
            if i == 1999 and retirement_year > 2001: 
                cola = 1.025 #Pursuant to Public Law 106-554
            pia_under_frozen_minumum*=cola  
            if i < 1982:
                pia_under_frozen_minumum =math.ceil(pia_under_frozen_minumum * 10) / 10
            else:
                pia_under_frozen_minumum =math.floor(pia_under_frozen_minumum * 10) / 10
        #print(piaAdjusted, pia_under_frozen_minumum)
        maximumFamilyBenefitFrozen = 183
        for i in range(birth_year + 65,reference_year): #This used to be birth + 62, but because of the special minimum, the PIA is now given indexed to the retirement year.
            cola = (1+cola_adjustments[i+1]) 
            if i == 1999 and retirement_year > 2001: 
                cola = 1.025 #Pursuant to Public Law 106-554
            maximumFamilyBenefitFrozen*=cola
        maximumFamilyBenefit = max(maximumFamilyBenefit, maximumFamilyBenefitFrozen)



    #print(birth_year + 62, reference_year)
    
    
    #print(cola)

    if retirement_year < 1982:
        maximumFamilyBenefit =math.ceil(maximumFamilyBenefit * 10) / 10
    else:
        maximumFamilyBenefit =math.floor(maximumFamilyBenefit * 10) / 10

    return maximumFamilyBenefit

def children_modern(income_stream:list, index_year:int, birth_year:int, retirement_year:int, reference_year:int,death_year:int, woman:bool, child_birth_year:int):
    """
    This function outputs the children's benefit under the primary's account under the relevant legislation.
     income_stream -- a list of nominal incomes a person received in each year.
        index_year -- the year in which an individual begins their income_stream.
        birth_year -- the year the individual is born.
        death_year -- the year which the primary died
        Reference year -- to which year would the dollars be indexed to. Likely the year in which the entitlement is being paid out.
    This function does NOT integrate current entitlement status. This should be done exogenously
    """
    childAge= reference_year - child_birth_year
    if childAge > 18 and reference_year > 1981: return 0
    if childAge > 22: return 0 #Students between 18-22 before 1981 can receive Social Security. We assume all applicants are students.
    primary_adjusted_income_stream=i_modern(income_stream, index_year, retirement_year)
    primary_avg_monthly_wage = a_modern(primary_adjusted_income_stream, index_year, birth_year, retirement_year,reference_year, woman, death_year)
    primary_PIA = bb_modern(income_stream, primary_avg_monthly_wage, index_year, birth_year, retirement_year,reference_year, woman)
    if reference_year<1981:
        if reference_year >= death_year: #If the primary is dead
            return math.ceil(0.75*primary_PIA*10)/10
        else: 
            return math.ceil(0.5* primary_PIA*10)/10
    else:
        if reference_year >= death_year: #If the primary is dead
            return math.floor(0.75*primary_PIA*10)/10
        else: 
            return math.floor(0.5* primary_PIA*10)/10